const FormInput = ({label, ...otherProps}) => {
    return(
        <div className="group">
            <label className={`${otherProps.value.length ? "shrink" : ""}`}>{label}</label>
            <input 
                {...otherProps}
            />
        </div>
    );
};


export default FormInput;
